import { getEarningBalance } from '~/client';

export const useEarningsBalance = defineQuery(() => {
  const {
    data: balance,
    error,
    isLoading,
    refetch,
  } = useQuery({
    key: () => ['balance'],
    query: () => getEarningBalance({ composable: '$fetch' }),
    staleTime: 0,
    enabled: () => useRoute().name === 'earnings-balance',
  });

  return {
    balance,
    total: computed(() => (balance.value?.pending || 0) + (balance.value?.ready_for_payment || 0)),
    error,
    isLoading,
    refetch,
  };
});
