import { createDisbursement } from '~/client';
import type { CreateDisbursementResponse } from '~/client';

export const useCreateDisbursement = defineMutation(() => {
  const { mutateAsync: createDisbursementMutation, asyncStatus } = useMutation({
    mutation: (): Promise<CreateDisbursementResponse> =>
      createDisbursement({
        composable: '$fetch',
      }),
    onSuccess: async () => {
      const queryCache = useQueryCache();
      queryCache.setQueryData(['balance'], (oldData: any) => {
        return {
          ...oldData,
          ready_for_payment: 0,
        };
      });
      showToastSuccess('Withdrawal initiated successfully.');
    },
    onError(error) {
      showToastError(error);
    },
  });

  return {
    createDisbursementMutation,
    isCreatingDisbursement: computed(() => asyncStatus.value === 'loading'),
  };
});
