<template>
  <section class="grid grid-cols-2 gap-6">
    <PageTitle class="col-span-2" title="Balance" show-doc />
    <AppLoader v-if="isLoadingEarningsInfo" subject="balance information" class="col-span-full" />
    <AppError
      v-else-if="earningsInfoError"
      class="col-span-2"
      :error="earningsInfoError"
      title="Failed to load balance information"
    />
    <AppEmpty v-else-if="!earnings" class="col-span-2" subject="balance information" />
    <template v-else>
      <LargeAlert
        v-if="earnings.status === 'not_registered'"
        description="Earnings are not available for canvassers who did not finish the onboarding process."
        variant="warning"
        card
        :icon="TriangleAlert"
        class="col-span-2 w-fit mx-auto"
      />
      <EarningsBranchInfoCard
        v-else-if="earnings.status === 'registered' && isAwaitingBranchUpdate === false"
        :status="earnings.status"
        :onboarding-link="earnings.onboarding_link"
        @open-branch-callback="isAwaitingBranchUpdate = true"
      />
      <EarningsProcessingBranchRegistration
        v-else-if="earnings.status === 'registered' && isAwaitingBranchUpdate === true"
      />
      <EarningsBranchActivated
        v-if="earnings.status === 'activated'"
        :is-need-dialog-show="isNeedDialogShow"
        :status="earnings.status"
        :onboarding-link="earnings.onboarding_link"
      />
      <template v-if="earnings.status === 'deactivated'">
        <Alert variant="warning" class="col-span-2 bg-card w-fit">
          <div class="flex items-center gap-2">
            <TriangleAlert class="size-5 stroke-warning-foreground min-w-5" />
            <div class="flex flex-col gap-1">
              <AlertTitle class="w-fit mb-0">Your Branch account is deactivated.</AlertTitle>
              <AlertDescription>Please contact your manager if you think this is a mistake.</AlertDescription>
            </div>
          </div>
        </Alert>
        <EarningsCurrentBalance :is-deactivated-account="true" />
        <EarningsBranchInfoCard :status="earnings.status" :onboarding-link="earnings.onboarding_link" />
      </template>
    </template>
  </section>
</template>

<script setup lang="ts">
import { TriangleAlert } from 'lucide-vue-next';
import { useEarnings } from '~/queries/earnings/details';

useHead({
  title: 'Earnings Balance',
});

definePageMeta({
  roles: ['canvasser'],
});

const isAwaitingBranchUpdate = ref<boolean>(false);

const { earnings, isLoading: isLoadingEarningsInfo, error: earningsInfoError } = useEarnings();

onUnmounted(() => {
  isAwaitingBranchUpdate.value = false;
});

const isNeedDialogShow = ref<boolean>(false);

watch(
  () => earnings.value?.status,
  (newValue, oldValue) => {
    console.log('Earnings status changed from', oldValue, 'to', newValue);
    if (oldValue === 'registered' && isAwaitingBranchUpdate.value === true && newValue === 'activated') {
      isNeedDialogShow.value = true;
      isAwaitingBranchUpdate.value = false;
    }
  }
);
</script>

<style scoped lang="scss"></style>
