<template>
  <Card class="col-span-2 xl:col-span-1">
    <CardHeader>
      <CardTitle>Current Balance</CardTitle>
    </CardHeader>
    <CardContent class="flex items-center">
      <AppLoader v-if="isLoading" variant="inline" subject="balance" />
      <AppError
        v-else-if="error"
        :error="error"
        title="Failed to load balance"
        variant="table"
        :action="refetch"
        action-text="Retry"
      />
      <AppEmpty v-else-if="!balance" subject="balance information" variant="table" />
      <div v-else class="grid gap-6 w-full max-w-[570px]">
        <div class="grid grid-cols-2 gap-2">
          <span class="text-lg">Available</span>
          <span class="text-xl text-right">{{ formatAmount(balance.ready_for_payment) }}</span>
          <span class="col-span-2 text-muted-foreground text-sm"
            >Will be paid automatically on
            <b>{{ formatDateTzToFormat(balance.next_payment_date, 'MM/dd/yyyy', timezone) }}</b>
          </span>
        </div>
        <div class="grid grid-cols-2 gap-2">
          <span class="text-lg">Pending</span>
          <span class="text-lg text-right">{{ formatAmount(balance.pending) }}</span>
          <span class="col-span-2 text-muted-foreground text-sm">Awaits confirmation from your manager</span>
        </div>
        <div class="grid grid-cols-2">
          <span class="text-lg font-bold">Total</span>
          <span class="text-xl font-bold text-right">{{ formatAmount(total) }}</span>
        </div>
      </div>
    </CardContent>
    <CardFooter v-if="balance && !isLoading && !error" class="flex-wrap gap-2">
      <Dialog v-model:open="isOpen">
        <DialogTrigger as-child>
          <Button
            :disabled="
              isDeactivatedAccount ||
              !balance.same_day_payout_enabled ||
              balance.ready_for_payment <= 0 ||
              isCreatingDisbursement
            "
            :loading="isCreatingDisbursement"
            >Withdraw {{ formatAmount(balance.ready_for_payment) }}</Button
          >
        </DialogTrigger>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>Withdraw Payment</DialogTitle>
            <DialogDescription>
              Are you sure you want to withdraw your available balance of
              <b>{{ formatAmount(balance?.ready_for_payment) }}</b
              >? This action cannot be undone.
            </DialogDescription>
            <DialogFooter>
              <DialogClose as-child>
                <Button variant="outline">Cancel</Button>
              </DialogClose>
              <Button
                :disabled="
                  isDeactivatedAccount ||
                  !balance.same_day_payout_enabled ||
                  balance.ready_for_payment <= 0 ||
                  isCreatingDisbursement
                "
                :loading="isCreatingDisbursement"
                @click="onWithdrawClick"
                >Confirm</Button
              >
            </DialogFooter>
          </DialogHeader>
        </DialogContent>
      </Dialog>
      <NuxtLink :to="{ name: 'earnings' }">
        <Button variant="outline">My Earnings</Button>
      </NuxtLink>
    </CardFooter>
  </Card>
</template>

<script lang="ts" setup>
import { useEarningsBalance } from '~/queries/earnings/balance';
import { useCreateDisbursement } from '~/mutations/earnings/withdraw';

interface Props {
  isDeactivatedAccount?: boolean;
}

withDefaults(defineProps<Props>(), {
  isDeactivatedAccount: false,
});

const { balance, isLoading, error, total, refetch } = useEarningsBalance();

const { timezone } = useUserRole();

const isOpen = ref<boolean>(false);

const { createDisbursementMutation, isCreatingDisbursement } = useCreateDisbursement();

async function onWithdrawClick() {
  await createDisbursementMutation()
    .then(() => {
      isOpen.value = false;
    })
    .catch((err) => {
      console.error('Error creating disbursement:', err);
    });
}
</script>
