<template>
  <LargeAlert
    class="col-span-2"
    title="Waiting for activation"
    description="Complete setting up your payment method on Branch."
    :icon="Spinner"
    card
    icon-class="stroke-destructive size-16 w-16"
  />
</template>

<script setup lang="ts">
import Spinner from '~/assets/icons/spinner.svg';
import { useEarnings } from '~/queries/earnings/details';

const { refetch, isLoading } = useEarnings();

useTimeoutPoll(async () => {
  if (!isLoading.value)
    await refetch().catch((error) => {
      console.error('Error refetching balance data:', error);
    });
}, 10000);
</script>
